  STRICT = 2,
  CR_EXPECTED = 25,
  LF_EXPECTED = 3,
  UNEXPECTED_CONTENT_LENGTH = 4,
  UNEXPECTED_SPACE = 30,
  CLOSED_CONNECTION = 5,
  INVALID_METHOD = 6,
  INVALID_URL = 7,
  INVALID_CONSTANT = 8,
