// -----------------------------------------------------------------------------
// character classes

function charTable(chars: (string | number)[]): Uint8Array {
  const t = new Uint8Array(256);
  for (const c of chars) t[typeof c === 'number' ? c : c.charCodeAt(0)] = 1;
  return t;
}
const ALPHA_L: string[] = [];
for (let i = 65; i <= 90; i++) ALPHA_L.push(String.fromCharCode(i), String.fromCharCode(i + 32));
const NUM_L = '0123456789'.split('');
const ALPHANUM_L = [...ALPHA_L, ...NUM_L];
const ALPHA = charTable(ALPHA_L);
const URL_CHAR = charTable([...'!"$%&\'()*+,-./:;<=>@[\\]^_`{|}~'.split(''), ...ALPHANUM_L]);
const USERINFO = charTable([...ALPHANUM_L, ...'-_.!~*\'()'.split(''), ...'%;:&=+$,'.split('')]);
const TOKEN = charTable([...'!#$%&\'*+-.^_`|~'.split(''), ...ALPHANUM_L]);
const headerChars: number[] = [9];
for (let i = 32; i <= 255; i++) if (i !== 127) headerChars.push(i);
const HEADER_CHARS = charTable(headerChars);
const CONNECTION_TOKEN_CHARS = charTable(headerChars.filter((c) => c !== 44));
const quoted: number[] = [9, 32];
for (let i = 0x21; i <= 0xff; i++) if (i !== 0x22 && i !== 0x5c) quoted.push(i);
const QUOTED_STRING = charTable(quoted);
const vchar: number[] = [9, 32];
for (let i = 0x21; i <= 0x7e; i++) vchar.push(i);
for (let i = 0x80; i <= 0xff; i++) vchar.push(i);
const HTAB_SP_VCHAR_OBS_TEXT = charTable(vchar);

function hexVal(c: number): number {
  if (c >= 48 && c <= 57) return c - 48;
  if (c >= 65 && c <= 70) return c - 55;
  if (c >= 97 && c <= 102) return c - 87;
  return -1;
}
const isDigit = (c: number) => c >= 48 && c <= 57;
const lower = (c: number) => (c >= 65 && c <= 90 ? c | 0x20 : c);

// -----------------------------------------------------------------------------
// tries (llparse compiles match/select edges with multi-byte keys into these)

interface Trie {
  next: (Trie | undefined)[];
  value: number; // -1: no key ends here
  leaf: boolean;
}

function buildTrie(entries: [string, number][]): Trie {
  const mk = (): Trie => ({ next: new Array(256), value: -1, leaf: true });
  const root = mk();
  for (const [k, v] of entries) {
    let n = root;
    for (let i = 0; i < k.length; i++) {
      const c = k.charCodeAt(i);
      n.leaf = false;
      n = n.next[c] ??= mk();
    }
    n.value = v;
  }
  return root;
}

const T_METHOD = buildTrie(Object.entries(METHODS));
const T_PROTO = buildTrie([['HTTP', 1], ['RTSP', 2], ['ICE', 3]]);
const T_SPECIAL_HEADERS = buildTrie([
  ['connection', HS_CONNECTION],
  ['content-length', HS_CONTENT_LENGTH],
  ['proxy-connection', HS_CONNECTION],
  ['transfer-encoding', HS_TRANSFER_ENCODING],
  ['upgrade', HS_UPGRADE],
]);
const T_CONNECTION = buildTrie([['close', HS_CONNECTION_CLOSE], ['upgrade', HS_CONNECTION_UPGRADE], ['keep-alive', HS_CONNECTION_KEEP_ALIVE]]);
const T_CHUNKED = buildTrie([['chunked', 1]]);
const T_SLASH2 = buildTrie([['//', 1]]);
const T_CRLF = buildTrie([['\r\n', 1]]);
const T_PRI = buildTrie([['\r\n\r\nSM\r\n\r\n', 1]]);

// results of a trie step
const TR_MORE = -1; // consumed, key not complete yet
const TR_MISMATCH = -2; // not consumed; take the node's otherwise edge
const TR_DONE = -3; // consumed, key complete (value in `trieValue`)
const TR_DONE_HERE = -4; // not consumed, a shorter key ended here (value in `trieValue`)

// -----------------------------------------------------------------------------
// spans

export const enum Span {
  NONE = 0,
  URL,
  STATUS,
  HEADER_FIELD,
  HEADER_VALUE,
  CHUNK_EXT_NAME,
  CHUNK_EXT_VALUE,
  BODY,
}

/** Callbacks (llhttp_settings_t). Return 0 to continue, or an llhttp errno. */
export interface Settings {
  onMessageBegin(): number;
  onSpan(kind: Span, data: Uint8Array, start: number, end: number): number;
  /** 0 normal, 1 skip body, 2 upgrade (skip body), 21 pause, anything else: error. */
  onHeadersComplete(): number;
  onMessageComplete(): number;
  onChunkHeader(): number;
  onChunkComplete(): number;
}

// -----------------------------------------------------------------------------
// states (llhttp node names)

