const TWO64_MINUS_1 = (1n << 64n) - 1n;

export class LLHTTP {
  type = TYPE_REQUEST;
  method = 0;
  http_major = 0;
  http_minor = 0;
  header_state = 0;
  lenient_flags = 0;
  upgrade = 0;
  finish = FINISH_SAFE;
  flags = 0;
  status_code = 0;
  initial_message_completed = 0;
  /** content_length as a number; exact value in `contentLengthBig` once it passes 2^48. */
  content_length = 0;
  contentLengthBig: bigint | null = null;

  error = 0;
  reason = '';
  /** Index into the buffer of the execute() that failed or paused. */
  error_pos = 0;

  private current = S.START;
  private spanPos = -1;
  private spanKind = Span.NONE;
  private trie: Trie | null = null;
  private trieValue = 0;
  private settings: Settings;

  constructor(type: number, settings: Settings) {
    this.settings = settings;
    this.init(type);
  }

  init(type: number) {
    this.type = type;
    this.method = 0;
    this.http_major = 0;
    this.http_minor = 0;
    this.header_state = 0;
    this.lenient_flags = 0;
    this.upgrade = 0;
    this.finish = FINISH_SAFE;
    this.flags = 0;
    this.status_code = 0;
    this.initial_message_completed = 0;
    this.content_length = 0;
    this.contentLengthBig = null;
    this.error = 0;
    this.reason = '';
    this.error_pos = 0;
    this.current = S.START;
    this.spanPos = -1;
    this.spanKind = Span.NONE;
    this.trie = null;
  }

  // ---------------------------------------------------------------------------
  // public API (api.c)

  execute(data: Uint8Array, start: number, end: number): number {
    if (this.error !== 0) return this.error;
    if (this.spanPos >= 0) this.spanPos = start;
    const r = this.run(data, start, end);
    if (r !== 0) return this.error;
    if (this.spanPos >= 0) {
      const err = this.settings.onSpan(this.spanKind, data, this.spanPos, end);
      if (err !== 0) {
        this.error = err;
        this.error_pos = end;
        return err;
      }
    }
    return 0;
  }

  /** llhttp_finish: does not touch `error`. */
  finishInput(): number {
    if (this.error !== 0) return 0;
    switch (this.finish) {
      case FINISH_SAFE_WITH_CB: {
        const err = this.settings.onMessageComplete();
        if (err !== 0) return err;
        return 0;
      }
      case FINISH_SAFE:
        return 0;
      default:
        this.reason = 'Invalid EOF state';
        return Err.INVALID_EOF_STATE;
    }
  }

  pause() {
    if (this.error !== 0) return;
    this.error = Err.PAUSED;
    this.reason = 'Paused';
  }

  resume() {
    if (this.error !== Err.PAUSED) return;
    this.error = 0;
  }

  resumeAfterUpgrade() {
    if (this.error !== Err.PAUSED_UPGRADE) return;
    this.error = 0;
  }

  messageNeedsEof(): boolean {
    if (this.type === TYPE_REQUEST) return false;
    const sc = this.status_code;
    if (((sc / 100) | 0) === 1 || sc === 204 || sc === 304 || this.flags & F_SKIPBODY) return false;
    if (this.flags & F_TRANSFER_ENCODING && (this.flags & F_CHUNKED) === 0) return true;
    if (this.flags & (F_CHUNKED | F_CONTENT_LENGTH)) return false;
    return true;
  }

  shouldKeepAlive(): boolean {
    if (this.http_major > 0 && this.http_minor > 0) {
      if (this.flags & F_CONNECTION_CLOSE) return false;
    } else if (!(this.flags & F_CONNECTION_KEEP_ALIVE)) {
      return false;
    }
    return !this.messageNeedsEof();
  }

  // ---------------------------------------------------------------------------
  // internal callbacks (http.c)

  private beforeHeadersComplete() {
    if (this.flags & F_UPGRADE && this.flags & F_CONNECTION_UPGRADE) {
      this.upgrade = this.type === TYPE_REQUEST || this.status_code === 101 ? 1 : 0;
    } else {
      this.upgrade = this.method === METHOD_CONNECT ? 1 : 0;
    }
  }

  private afterHeadersComplete(): number {
    const hasBody = this.flags & F_CHUNKED || this.content_length > 0;
    if (
      (this.upgrade && (this.method === METHOD_CONNECT || this.flags & F_SKIPBODY || !hasBody)) ||
      (this.type === TYPE_RESPONSE && this.status_code === 101)
    ) {
      return 1;
    }
    if (this.type === TYPE_RESPONSE && this.status_code === 100) return 0;
    if (
      this.flags & F_SKIPBODY ||
      (this.type === TYPE_RESPONSE && (this.status_code === 102 || this.status_code === 103 || this.status_code === 204 || this.status_code === 304))
    ) {
      return 0;
    } else if (this.flags & F_CHUNKED) {
      return 2;
    } else if (this.flags & F_TRANSFER_ENCODING) {
      if (this.type === TYPE_REQUEST && (this.lenient_flags & LENIENT_CHUNKED_LENGTH) === 0 && (this.lenient_flags & LENIENT_TRANSFER_ENCODING) === 0) {
        return 5;
      }
      return 4;
    } else if (!(this.flags & F_CONTENT_LENGTH)) {
      return this.messageNeedsEof() ? 4 : 0;
    } else if (this.content_length === 0) {
      return 0;
    }
    return 3;
  }

  private afterMessageComplete(): number {
    const keep = this.shouldKeepAlive();
    this.finish = FINISH_SAFE;
    this.flags = 0;
    return keep ? 1 : 0;
  }

  /** mul_add on content_length; returns true on overflow (unsigned 64-bit, like llhttp). */
  private mulAddContentLength(base: number, digit: number): boolean {
    if (this.contentLengthBig === null && this.content_length < 2 ** 48) {
      this.content_length = this.content_length * base + digit;
      return false;
    }
    let v = this.contentLengthBig ?? BigInt(this.content_length);
    v = v * BigInt(base) + BigInt(digit);
    if (v > TWO64_MINUS_1) return true;
    this.contentLengthBig = v;
    this.content_length = Number(v);
    return false;
  }

  private setContentLength(v: number) {
    this.content_length = v;
    this.contentLengthBig = null;
  }

  // ---------------------------------------------------------------------------
  // the machine

  private stepTrie(root: Trie, c: number): number {
    const node = this.trie ?? root;
    const child = node.next[c];
    if (child !== undefined) {
      if (child.leaf) {
        this.trie = null;
        this.trieValue = child.value;
        return TR_DONE;
      }
      this.trie = child;
      return TR_MORE;
    }
    this.trie = null;
    if (node !== root && node.value >= 0) {
      this.trieValue = node.value;
      return TR_DONE_HERE;
    }
    return TR_MISMATCH;
  }

  /** Records an error at `pos` and returns it. */
  private fail(code: number, reason: string, pos: number): number {
    this.error = code;
    this.reason = reason;
    this.error_pos = pos;
    this.current = S.ERROR;
    return code;
  }

  /** A callback error/pause raised at `pos`; parsing resumes at `next` after a pause. */
  private cbFail(code: number, pos: number, next: S): number {
    this.error = code;
    this.error_pos = pos;
    this.current = next;
    return code;
  }

  private spanStart(kind: Span, p: number) {
    this.spanPos = p;
    this.spanKind = kind;
  }

  private spanEnd(data: Uint8Array, p: number): number {
    const start = this.spanPos;
    this.spanPos = -1;
    return this.settings.onSpan(this.spanKind, data, start, p);
  }

  private lenient(flag: number): boolean {
    return (this.lenient_flags & flag) !== 0;
  }

  /** Runs the machine over data[start, end). Returns 0 when the input ran out, else the error. */
  private run(data: Uint8Array, start: number, end: number): number {
    let p = start;
    let s = this.current;
    let r: number;
    let c: number;
    for (;;) {
      switch (s) {
        case S.ERROR:
          return this.error || this.fail(Err.INTERNAL, 'Invalid state', p);

        // ---------------------------------------------------------------- start
        case S.START:
          if (p === end) break;
          c = data[p];
          if (c === 13 || c === 10) {
            p++;
            continue;
          }
          // on_reset is null in Node
          s = S.AFTER_START;
          continue;

        case S.AFTER_START:
          this.finish = FINISH_UNSAFE;
          r = this.settings.onMessageBegin();
          if (r !== 0) {
            if (r === Err.PAUSED) return this.pauseAt('on_message_begin pause', p, S.SWITCH_TYPE);
            return this.fail(Err.CB_MESSAGE_BEGIN, '`on_message_begin` callback error', p);
          }
          s = S.SWITCH_TYPE;
          continue;

        case S.SWITCH_TYPE:
          // type BOTH is not used by Node (initialize() only accepts REQUEST or RESPONSE)
          s = this.type === TYPE_RESPONSE ? S.START_RES : S.START_REQ;
          continue;

        // ---------------------------------------------------------------- request line
        case S.START_REQ:
          if (p === end) break; // method span start
          s = S.AFTER_START_REQ;
          continue;

        case S.AFTER_START_REQ:
          if (p === end) break;
          r = this.stepTrie(T_METHOD, data[p]);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_MISMATCH) return this.fail(Err.INVALID_METHOD, 'Invalid method encountered', p);
          if (r === TR_DONE) p++;
          this.method = this.trieValue;
          s = S.REQ_FIRST_SPACE_BEFORE_URL;
          continue;

        case S.REQ_FIRST_SPACE_BEFORE_URL:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            s = S.REQ_SPACES_BEFORE_URL;
            continue;
          }
          return this.fail(Err.INVALID_METHOD, 'Expected space after method', p);

        case S.REQ_SPACES_BEFORE_URL:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            continue;
          }
          s = this.method === METHOD_CONNECT ? S.URL_ENTRY_CONNECT : S.URL_ENTRY_NORMAL;
          continue;

        // ---------------------------------------------------------------- url (url.ts)
        case S.URL_ENTRY_NORMAL:
        case S.URL_ENTRY_CONNECT:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          this.spanStart(Span.URL, p);
          s = s === S.URL_ENTRY_CONNECT ? S.URL_SERVER : S.URL_START;
          continue;

        case S.URL_START:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12 || c === 32 || c === 13 || c === 10) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (c === 47 || c === 42) {
            p++;
            s = S.URL_PATH;
            continue;
          }
          if (ALPHA[c]) {
            s = S.URL_SCHEMA;
            continue;
          }
          return this.fail(Err.INVALID_URL, 'Unexpected start char in url', p);

        case S.URL_SCHEMA:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12 || c === 32 || c === 13 || c === 10) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (ALPHA[c]) {
            p++;
            continue;
          }
          if (c === 58) {
            p++;
            s = S.URL_SCHEMA_DELIM;
            continue;
          }
          return this.fail(Err.INVALID_URL, 'Unexpected char in url schema', p);

        case S.URL_SCHEMA_DELIM:
          if (p === end) break;
          c = data[p];
          if (this.trie === null && (c === 9 || c === 12 || c === 32 || c === 13 || c === 10)) {
            return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          }
          r = this.stepTrie(T_SLASH2, c);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) {
            p++;
            s = S.URL_SERVER;
            continue;
          }
          return this.fail(Err.INVALID_URL, 'Unexpected char in url schema', p);

        case S.URL_SERVER:
        case S.URL_SERVER_WITH_AT:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (c === 47) {
            p++;
            s = S.URL_PATH;
            continue;
          }
          if (c === 63) {
            p++;
            s = S.URL_QUERY;
            continue;
          }
          if (USERINFO[c] || c === 91 || c === 93) {
            p++;
            s = S.URL_SERVER;
            continue;
          }
          if (c === 64) {
            if (s === S.URL_SERVER_WITH_AT) return this.fail(Err.INVALID_URL, 'Double @ in url', p + 1);
            p++;
            s = S.URL_SERVER_WITH_AT;
            continue;
          }
          r = this.urlEnd(data, p, c);
          if (r === 0) {
            s = this.current;
            continue;
          }
          if (r > 0) return r;
          return this.fail(Err.INVALID_URL, 'Unexpected char in url server', p);

        case S.URL_PATH:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (URL_CHAR[c]) {
            p++;
            continue;
          }
          s = S.URL_QUERY_OR_FRAGMENT;
          continue;

        case S.URL_QUERY_OR_FRAGMENT:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (c === 63) {
            p++;
            s = S.URL_QUERY;
            continue;
          }
          if (c === 35) {
            p++;
            s = S.URL_FRAGMENT;
            continue;
          }
          r = this.urlEnd(data, p, c);
          if (r === 0) {
            s = this.current;
            continue;
          }
          if (r > 0) return r;
          return this.fail(Err.INVALID_URL, 'Invalid char in url path', p);

        case S.URL_QUERY:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (URL_CHAR[c] || c === 63) {
            p++;
            continue;
          }
          if (c === 35) {
            p++;
            s = S.URL_FRAGMENT;
            continue;
          }
          r = this.urlEnd(data, p, c);
          if (r === 0) {
            s = this.current;
            continue;
          }
          if (r > 0) return r;
          return this.fail(Err.INVALID_URL, 'Invalid char in url query', p);

        case S.URL_FRAGMENT:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          if (URL_CHAR[c] || c === 63 || c === 35) {
            p++;
            continue;
          }
          r = this.urlEnd(data, p, c);
          if (r === 0) {
            s = this.current;
            continue;
          }
          if (r > 0) return r;
          return this.fail(Err.INVALID_URL, 'Invalid char in url fragment start', p);

        case S.URL_SKIP_TO_HTTP:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          p++;
          s = S.URL_TO_HTTP;
          continue;

        case S.URL_TO_HTTP:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          // on_url_complete is null in Node
          s = S.REQ_HTTP_START;
          continue;

        case S.URL_SKIP_LF_TO_HTTP09:
          if (p === end) break;
          c = data[p];
          if (this.trie === null && (c === 9 || c === 12)) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          r = this.stepTrie(T_CRLF, c);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) {
            p++;
            s = S.URL_TO_HTTP09;
            continue;
          }
          return this.fail(Err.INVALID_URL, 'Expected CRLF', p);

        case S.URL_SKIP_TO_HTTP09:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          p++;
          s = S.URL_TO_HTTP09;
          continue;

        case S.URL_TO_HTTP09:
          if (p === end) break;
          c = data[p];
          if (c === 9 || c === 12) return this.fail(Err.INVALID_URL, 'Invalid characters in url', p + 1);
          this.http_major = 0;
          this.http_minor = 9;
          s = S.HEADERS_START;
          continue;

        // ---------------------------------------------------------------- request version
        case S.REQ_HTTP_START:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            continue;
          }
          s = S.REQ_AFTER_HTTP_START; // protocol span start
          continue;

        case S.REQ_AFTER_HTTP_START: {
          if (p === end) break;
          r = this.stepTrie(T_PROTO, data[p]);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r !== TR_DONE) return this.fail(Err.INVALID_CONSTANT, 'Expected HTTP/, RTSP/ or ICE/', p);
          p++;
          const proto = this.trieValue;
          if (proto === 1 && !METHODS_HTTP.has(this.method)) return this.fail(Err.INVALID_CONSTANT, 'Invalid method for HTTP/x.x request', p);
          if (proto === 2 && !METHODS_RTSP.has(this.method)) return this.fail(Err.INVALID_CONSTANT, 'Invalid method for RTSP/x.x request', p);
          if (proto === 3 && !METHODS_ICE.has(this.method)) return this.fail(Err.INVALID_CONSTANT, 'Expected SOURCE method for ICE/x.x request', p);
          s = S.REQ_AFTER_PROTOCOL;
          continue;
        }

        case S.REQ_AFTER_PROTOCOL:
          if (p === end) break;
          if (data[p] === 47) {
            p++;
            s = S.REQ_HTTP_MAJOR;
            continue;
          }
          return this.fail(Err.INVALID_CONSTANT, 'Expected HTTP/, RTSP/ or ICE/', p);

        case S.REQ_HTTP_MAJOR:
        case S.RES_HTTP_MAJOR:
          if (p === end) break;
          c = data[p];
          if (isDigit(c)) {
            p++;
            this.http_major = c - 48;
            s = s === S.REQ_HTTP_MAJOR ? S.REQ_HTTP_DOT : S.RES_HTTP_DOT;
            continue;
          }
          return this.fail(Err.INVALID_VERSION, 'Invalid major version', p);

        case S.REQ_HTTP_DOT:
        case S.RES_HTTP_DOT:
          if (p === end) break;
          if (data[p] === 46) {
            p++;
            s = s === S.REQ_HTTP_DOT ? S.REQ_HTTP_MINOR : S.RES_HTTP_MINOR;
            continue;
          }
          return this.fail(Err.INVALID_VERSION, 'Expected dot', p);

        case S.REQ_HTTP_MINOR:
        case S.RES_HTTP_MINOR:
          if (p === end) break;
          c = data[p];
          if (!isDigit(c)) return this.fail(Err.INVALID_VERSION, 'Invalid minor version', p);
          p++;
          this.http_minor = c - 48;
          if (!this.versionOk()) return this.fail(Err.INVALID_VERSION, 'Invalid HTTP version', p);
          // on_version_complete is null in Node
          if (s === S.RES_HTTP_MINOR) {
            s = S.RES_AFTER_VERSION;
            continue;
          }
          s = this.method === METHOD_PRI ? S.REQ_PRI_UPGRADE : S.REQ_HTTP_COMPLETE;
          continue;

        case S.REQ_HTTP_COMPLETE:
          if (p === end) break;
          c = data[p];
          if (c === 13) {
            p++;
            s = S.REQ_HTTP_COMPLETE_CRLF;
            continue;
          }
          if (c === 10 && this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
            p++;
            s = S.REQ_HTTP_COMPLETE_CRLF;
            continue;
          }
          return this.fail(Err.INVALID_VERSION, 'Expected CRLF after version', c === 10 ? p + 1 : p);

        case S.REQ_HTTP_COMPLETE_CRLF:
          if (p === end) break;
          if (data[p] === 10) {
            p++;
            s = S.HEADERS_START;
            continue;
          }
          if (this.lenient(LENIENT_OPTIONAL_LF_AFTER_CR)) {
            s = S.HEADERS_START;
            continue;
          }
          return this.fail(Err.STRICT, 'Expected CRLF after version', p);

        case S.REQ_PRI_UPGRADE:
          if (p === end) break;
          r = this.stepTrie(T_PRI, data[p]);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) return this.fail(Err.PAUSED_H2_UPGRADE, 'Pause on PRI/Upgrade', p + 1);
          return this.fail(Err.INVALID_VERSION, 'Expected HTTP/2 Connection Preface', p);

        // ---------------------------------------------------------------- status line
        case S.START_RES:
          if (p === end) break; // protocol span start
          s = S.RES_AFTER_START;
          continue;

        case S.RES_AFTER_START:
          if (p === end) break;
          r = this.stepTrie(T_PROTO, data[p]);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r !== TR_DONE) return this.fail(Err.INVALID_CONSTANT, 'Expected HTTP/, RTSP/ or ICE/', p);
          p++;
          s = S.RES_AFTER_PROTOCOL;
          continue;

        case S.RES_AFTER_PROTOCOL:
          if (p === end) break;
          if (data[p] === 47) {
            p++;
            s = S.RES_HTTP_MAJOR;
            continue;
          }
          return this.fail(Err.INVALID_CONSTANT, 'Expected HTTP/, RTSP/ or ICE/', p);

        case S.RES_AFTER_VERSION:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            this.status_code = 0;
            s = S.RES_STATUS_CODE_DIGIT_1;
            continue;
          }
          return this.fail(Err.INVALID_VERSION, 'Expected space after version', p);

        case S.RES_STATUS_CODE_DIGIT_1:
        case S.RES_STATUS_CODE_DIGIT_2:
        case S.RES_STATUS_CODE_DIGIT_3:
          if (p === end) break;
          c = data[p];
          if (!isDigit(c)) return this.fail(Err.INVALID_STATUS, 'Invalid status code', p);
          p++;
          this.status_code = this.status_code * 10 + (c - 48);
          s = s === S.RES_STATUS_CODE_DIGIT_1 ? S.RES_STATUS_CODE_DIGIT_2 : s === S.RES_STATUS_CODE_DIGIT_2 ? S.RES_STATUS_CODE_DIGIT_3 : S.RES_STATUS_CODE_OTHERWISE;
          continue;

        case S.RES_STATUS_CODE_OTHERWISE:
          if (p === end) break;
          c = data[p];
          if (c === 32) {
            p++;
            s = S.RES_STATUS_START;
            continue;
          }
          if (c === 13) {
            p++;
            s = S.RES_LINE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            p++;
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.HEADERS_START; // on_status_complete is null in Node
              continue;
            }
            return this.fail(Err.INVALID_STATUS, 'Invalid response status', p);
          }
          return this.fail(Err.INVALID_STATUS, 'Invalid response status', p);

        case S.RES_STATUS_START:
          if (p === end) break;
          this.spanStart(Span.STATUS, p);
          s = S.RES_STATUS;
          continue;

        case S.RES_STATUS:
          if (p === end) break;
          c = data[p];
          if (c === 13) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.RES_LINE_ALMOST_DONE);
            p++;
            s = S.RES_LINE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.HEADERS_START);
            p++;
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.HEADERS_START;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after response line', p);
          }
          p++;
          continue;

        case S.RES_LINE_ALMOST_DONE:
          if (p === end) break;
          c = data[p];
          if (c === 13 || c === 10) {
            p++;
            s = S.HEADERS_START;
            continue;
          }
          if (this.lenient(LENIENT_OPTIONAL_LF_AFTER_CR)) {
            s = S.HEADERS_START;
            continue;
          }
          return this.fail(Err.STRICT, 'Expected LF after CR', p);

        // ---------------------------------------------------------------- header fields
        case S.HEADERS_START:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            if (this.lenient(LENIENT_HEADERS)) {
              s = S.HEADER_FIELD_START;
              continue;
            }
            return this.fail(Err.UNEXPECTED_SPACE, 'Unexpected space after start line', p);
          }
          s = S.HEADER_FIELD_START;
          continue;

        case S.HEADER_FIELD_START:
          if (p === end) break;
          c = data[p];
          if (c === 13) {
            p++;
            s = S.HEADERS_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            p++;
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              r = this.checkTrailing(p);
              if (r < 0) {
                s = -r as S;
                continue;
              }
              return r;
            }
            return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header field char', p);
          }
          if (c === 58) return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header token', p);
          this.spanStart(Span.HEADER_FIELD, p);
          s = S.HEADER_FIELD;
          continue;

        case S.HEADER_FIELD:
          if (p === end) break;
          r = this.stepTrie(T_SPECIAL_HEADERS, lower(data[p]));
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_MISMATCH) {
            this.header_state = HS_GENERAL;
            s = S.HEADER_FIELD_GENERAL;
            continue;
          }
          if (r === TR_DONE) p++;
          this.header_state = this.trieValue;
          s = S.HEADER_FIELD_COLON;
          continue;

        case S.HEADER_FIELD_COLON:
          if (p === end) break;
          c = data[p];
          if (c === 32) {
            if (this.lenient(LENIENT_HEADERS)) {
              s = S.HEADER_FIELD_COLON_DISCARD_WS;
              continue;
            }
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
            return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header field char', p + 1);
          }
          if (c === 58) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.HEADER_FIELD_COMPLETE);
            p++;
            s = S.HEADER_FIELD_COMPLETE;
            continue;
          }
          this.header_state = HS_GENERAL;
          s = S.HEADER_FIELD_GENERAL;
          continue;

        case S.HEADER_FIELD_COLON_DISCARD_WS:
          if (p === end) break;
          if (data[p] === 32) {
            p++;
            continue;
          }
          s = S.HEADER_FIELD_COLON;
          continue;

        case S.HEADER_FIELD_GENERAL:
          if (p === end) break;
          c = data[p];
          if (TOKEN[c]) {
            p++;
            continue;
          }
          if (c === 58) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.HEADER_FIELD_COMPLETE);
            p++;
            s = S.HEADER_FIELD_COMPLETE;
            continue;
          }
          return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header token', p);

        case S.HEADER_FIELD_COMPLETE:
          // on_header_field_complete is null in Node
          if (this.header_state === HS_TRANSFER_ENCODING) {
            if (this.flags & F_CONTENT_LENGTH && !this.lenient(LENIENT_CHUNKED_LENGTH)) {
              return this.fail(Err.INVALID_TRANSFER_ENCODING, "Transfer-Encoding can't be present with Content-Length", p);
            }
          } else if (this.header_state === HS_CONTENT_LENGTH) {
            if (this.flags & F_TRANSFER_ENCODING && !this.lenient(LENIENT_CHUNKED_LENGTH)) {
              return this.fail(Err.INVALID_CONTENT_LENGTH, "Content-Length can't be present with Transfer-Encoding", p);
            }
          }
          s = S.HEADER_VALUE_DISCARD_WS;
          continue;

        // ---------------------------------------------------------------- header values
        case S.HEADER_VALUE_DISCARD_WS:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 9) {
            p++;
            continue;
          }
          if (c === 13) {
            p++;
            s = S.HEADER_VALUE_DISCARD_WS_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            p++;
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.HEADER_VALUE_DISCARD_LWS;
              continue;
            }
            return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header value char', p);
          }
          s = S.HEADER_VALUE_START_SPAN;
          continue;

        case S.HEADER_VALUE_START_SPAN:
          if (p === end) break;
          this.spanStart(Span.HEADER_VALUE, p);
          s = S.HEADER_VALUE_START;
          continue;

        case S.HEADER_VALUE_DISCARD_WS_ALMOST_DONE:
          if (p === end) break;
          if (data[p] === 10) {
            p++;
            s = S.HEADER_VALUE_DISCARD_LWS;
            continue;
          }
          if (this.lenient(LENIENT_HEADERS)) {
            s = S.HEADER_VALUE_DISCARD_LWS;
            continue;
          }
          return this.fail(Err.STRICT, 'Expected LF after CR', p);

        case S.HEADER_VALUE_DISCARD_LWS:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 9) {
            p++;
            if (this.lenient(LENIENT_HEADERS)) {
              s = S.HEADER_VALUE_DISCARD_WS;
              continue;
            }
            return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header value char', p);
          }
          if (this.header_state === HS_CONTENT_LENGTH) return this.fail(Err.INVALID_CONTENT_LENGTH, 'Empty Content-Length', p);
          this.setHeaderFlags();
          // empty span: the span start node needs a byte, which is here
          this.spanStart(Span.HEADER_VALUE, p);
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p, S.HEADER_FIELD_START);
          s = S.HEADER_FIELD_START; // on_header_value_complete is null in Node
          continue;

        case S.HEADER_VALUE_START:
          switch (this.header_state) {
            case HS_UPGRADE:
              this.flags |= F_UPGRADE;
              this.header_state = HS_GENERAL;
              s = S.HEADER_VALUE;
              continue;
            case HS_TRANSFER_ENCODING:
              if (this.flags & F_CHUNKED && this.type === TYPE_REQUEST && !this.lenient(LENIENT_TRANSFER_ENCODING)) {
                r = this.spanEnd(data, p);
                if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
                return this.fail(Err.INVALID_TRANSFER_ENCODING, 'Invalid `Transfer-Encoding` header value', p + 1);
              }
              this.flags |= F_TRANSFER_ENCODING;
              this.flags &= ~F_CHUNKED;
              s = S.HEADER_VALUE_TE_CHUNKED;
              continue;
            case HS_CONTENT_LENGTH:
              if (this.flags & F_CONTENT_LENGTH) return this.fail(Err.UNEXPECTED_CONTENT_LENGTH, 'Duplicate Content-Length', p);
              s = S.HEADER_VALUE_CONTENT_LENGTH;
              continue;
            case HS_CONNECTION:
              s = S.HEADER_VALUE_CONNECTION;
              continue;
            default:
              s = S.HEADER_VALUE;
              continue;
          }

        case S.HEADER_VALUE_TE_CHUNKED:
          if (p === end) break;
          r = this.stepTrie(T_CHUNKED, data[p] | 0x20);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) {
            p++;
            s = S.HEADER_VALUE_TE_CHUNKED_LAST;
            continue;
          }
          s = S.HEADER_VALUE_TE_TOKEN;
          continue;

        case S.HEADER_VALUE_TE_CHUNKED_LAST:
          if (p === end) break;
          c = data[p];
          if (c === 32) {
            p++;
            continue;
          }
          if (c === 13 || c === 10) {
            this.header_state = HS_TRANSFER_ENCODING_CHUNKED;
            s = S.HEADER_VALUE_OTHERWISE;
            continue;
          }
          if (c === 44) {
            if (this.type === TYPE_REQUEST && !this.lenient(LENIENT_TRANSFER_ENCODING)) {
              r = this.spanEnd(data, p);
              if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
              return this.fail(Err.INVALID_TRANSFER_ENCODING, 'Invalid `Transfer-Encoding` header value', p + 1);
            }
            s = S.HEADER_VALUE_TE_CHUNKED;
            continue;
          }
          s = S.HEADER_VALUE_TE_TOKEN;
          continue;

        case S.HEADER_VALUE_TE_TOKEN:
          if (p === end) break;
          c = data[p];
          if (c === 44) {
            p++;
            s = S.HEADER_VALUE_TE_TOKEN_OWS;
            continue;
          }
          if (CONNECTION_TOKEN_CHARS[c]) {
            p++;
            continue;
          }
          this.header_state = HS_GENERAL;
          s = S.HEADER_VALUE;
          continue;

        case S.HEADER_VALUE_TE_TOKEN_OWS:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 9) {
            p++;
            continue;
          }
          s = S.HEADER_VALUE_TE_CHUNKED;
          continue;

        case S.HEADER_VALUE_CONTENT_LENGTH:
          if (p === end) break;
          c = data[p];
          if (isDigit(c)) {
            p++;
            if (this.mulAddContentLength(10, c - 48)) {
              r = this.spanEnd(data, p);
              if (r !== 0) return this.cbFail(r, p, S.ERROR);
              return this.fail(Err.INVALID_CONTENT_LENGTH, 'Content-Length overflow', p);
            }
            continue;
          }
          s = S.HEADER_VALUE_CONTENT_LENGTH_WS;
          continue;

        case S.HEADER_VALUE_CONTENT_LENGTH_WS:
          if (p === end) break;
          c = data[p];
          if (c === 32) {
            p++;
            continue;
          }
          if (c === 13 || c === 10) {
            this.flags |= F_CONTENT_LENGTH;
            s = S.HEADER_VALUE_OTHERWISE;
            continue;
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p, S.ERROR);
          return this.fail(Err.INVALID_CONTENT_LENGTH, 'Invalid character in Content-Length', p);

        case S.HEADER_VALUE_CONNECTION:
          if (p === end) break;
          c = lower(data[p]);
          if (this.trie === null && (c === 32 || c === 9)) {
            p++;
            continue;
          }
          r = this.stepTrie(T_CONNECTION, c);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) {
            p++;
            this.header_state = this.trieValue;
            s = S.HEADER_VALUE_CONNECTION_WS;
            continue;
          }
          s = S.HEADER_VALUE_CONNECTION_TOKEN;
          continue;

        case S.HEADER_VALUE_CONNECTION_WS:
          if (p === end) break;
          c = data[p];
          if (c === 44) {
            p++;
            this.setHeaderFlags();
            s = S.HEADER_VALUE_CONNECTION;
            continue;
          }
          if (c === 32) {
            p++;
            continue;
          }
          if (c === 13 || c === 10) {
            s = S.HEADER_VALUE_OTHERWISE;
            continue;
          }
          this.header_state = HS_GENERAL;
          s = S.HEADER_VALUE_CONNECTION_TOKEN;
          continue;

        case S.HEADER_VALUE_CONNECTION_TOKEN:
          if (p === end) break;
          c = data[p];
          if (c === 44) {
            p++;
            s = S.HEADER_VALUE_CONNECTION;
            continue;
          }
          if (CONNECTION_TOKEN_CHARS[c]) {
            p++;
            continue;
          }
          s = S.HEADER_VALUE_OTHERWISE;
          continue;

        case S.HEADER_VALUE:
          if (p === end) break;
          // fast path over plain header bytes
          while (p < end && HEADER_CHARS[data[p]]) p++;
          if (p === end) break;
          s = S.HEADER_VALUE_OTHERWISE;
          continue;

        case S.HEADER_VALUE_OTHERWISE:
          if (p === end) break;
          c = data[p];
          if (c === 13) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.HEADER_VALUE_ALMOST_DONE);
            p++;
            s = S.HEADER_VALUE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, S.ERROR);
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.HEADER_VALUE_ALMOST_DONE;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after header value', p);
          }
          if (this.lenient(LENIENT_HEADERS)) {
            s = S.HEADER_VALUE_LENIENT;
            continue;
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p, S.ERROR);
          return this.fail(Err.INVALID_HEADER_TOKEN, 'Invalid header value char', p);

        case S.HEADER_VALUE_LENIENT:
          if (p === end) break;
          c = data[p];
          if (c === 13) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.HEADER_VALUE_ALMOST_DONE);
            p++;
            s = S.HEADER_VALUE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, S.HEADER_VALUE_ALMOST_DONE);
            s = S.HEADER_VALUE_ALMOST_DONE;
            continue;
          }
          p++;
          continue;

        case S.HEADER_VALUE_ALMOST_DONE:
          if (p === end) break;
          if (data[p] === 10) {
            p++;
            s = S.HEADER_VALUE_LWS;
            continue;
          }
          return this.fail(Err.LF_EXPECTED, 'Missing expected LF after header value', p);

        case S.HEADER_VALUE_LWS:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 9) {
            if (!this.lenient(LENIENT_HEADERS)) return this.fail(Err.INVALID_HEADER_TOKEN, 'Unexpected whitespace after header value', p);
            if (this.header_state === HS_TRANSFER_ENCODING_CHUNKED) this.header_state = HS_GENERAL;
            this.spanStart(Span.HEADER_VALUE, p);
            s = S.HEADER_VALUE_START;
            continue;
          }
          this.setHeaderFlags();
          s = S.HEADER_FIELD_START; // on_header_value_complete is null in Node
          continue;

        case S.HEADERS_ALMOST_DONE:
          if (p === end) break;
          if (data[p] === 10) {
            p++;
          } else if (!this.lenient(LENIENT_OPTIONAL_LF_AFTER_CR)) {
            return this.fail(Err.STRICT, 'Expected LF after headers', p);
          }
          r = this.checkTrailing(p);
          if (r < 0) {
            s = -r as S;
            continue;
          }
          return r;

        case S.HEADERS_DONE:
          switch (this.afterHeadersComplete()) {
            case 1:
              r = this.settings.onMessageComplete();
              if (r !== 0) {
                if (r === Err.PAUSED) return this.pauseAt('on_message_complete pause', p, S.UPGRADE_PAUSE);
                return this.fail(Err.CB_MESSAGE_COMPLETE, '`on_message_complete` callback error', p);
              }
              s = S.UPGRADE_PAUSE;
              continue;
            case 2:
              s = S.CHUNK_SIZE_START;
              continue;
            case 3:
              s = S.BODY_IDENTITY;
              continue;
            case 4:
              s = S.BODY_IDENTITY_EOF;
              continue;
            case 5:
              return this.fail(Err.INVALID_TRANSFER_ENCODING, 'Request has invalid `Transfer-Encoding`', p);
            default:
              r = this.settings.onMessageComplete();
              if (r !== 0) {
                if (r === Err.PAUSED) return this.pauseAt('on_message_complete pause', p, S.CLEANUP);
                return this.fail(Err.CB_MESSAGE_COMPLETE, '`on_message_complete` callback error', p);
              }
              s = S.CLEANUP;
              continue;
          }

        // ---------------------------------------------------------------- bodies
        case S.BODY_IDENTITY:
          if (p === end) break;
          this.spanStart(Span.BODY, p);
          s = S.BODY_IDENTITY_CONSUME;
          continue;

        case S.BODY_IDENTITY_CONSUME:
        case S.CHUNK_DATA_CONSUME: {
          if (p === end) break;
          const avail = end - p;
          const need = this.content_length;
          if (avail >= need) {
            p += need;
            this.setContentLength(0);
            const next = s === S.BODY_IDENTITY_CONSUME ? S.MESSAGE_DONE : S.CHUNK_DATA_ALMOST_DONE;
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, next);
            s = next;
            continue;
          }
          if (this.contentLengthBig !== null) {
            this.contentLengthBig -= BigInt(avail);
            this.content_length = Number(this.contentLengthBig);
          } else {
            this.content_length -= avail;
          }
          p = end;
          break;
        }

        case S.BODY_IDENTITY_EOF:
          this.finish = FINISH_SAFE_WITH_CB;
          s = S.BODY_IDENTITY_EOF_SPAN;
          continue;

        case S.BODY_IDENTITY_EOF_SPAN:
          if (p === end) break;
          this.spanStart(Span.BODY, p);
          s = S.EOF;
          continue;

        case S.EOF:
          // read everything until the connection ends
          p = end;
          break;

        case S.MESSAGE_DONE:
          r = this.settings.onMessageComplete();
          if (r !== 0) {
            if (r === Err.PAUSED) return this.pauseAt('on_message_complete pause', p, S.UPGRADE_AFTER_DONE);
            return this.fail(Err.CB_MESSAGE_COMPLETE, '`on_message_complete` callback error', p);
          }
          s = S.UPGRADE_AFTER_DONE;
          continue;

        case S.UPGRADE_AFTER_DONE:
          s = this.upgrade === 1 ? S.UPGRADE_PAUSE : S.CLEANUP;
          continue;

        case S.UPGRADE_PAUSE:
          // the rest of the stream is in a different protocol
          return this.pauseAt('Pause on CONNECT/Upgrade', p, S.CLEANUP, Err.PAUSED_UPGRADE);

        case S.CLEANUP:
          if (this.afterMessageComplete() === 1) {
            this.setContentLength(0);
            s = S.RESTART;
            continue;
          }
          this.finish = FINISH_SAFE;
          s = this.lenient(LENIENT_KEEP_ALIVE) ? S.RESTART : S.CLOSED;
          continue;

        case S.CLOSED:
          if (p === end) break;
          c = data[p];
          if (c === 13 || c === 10) {
            p++;
            continue;
          }
          p++;
          if (this.lenient(LENIENT_DATA_AFTER_CLOSE)) continue;
          return this.fail(Err.CLOSED_CONNECTION, 'Data after `Connection: close`', p);

        case S.RESTART:
          this.initial_message_completed = 1;
          this.finish = FINISH_SAFE;
          s = S.START;
          continue;

        // ---------------------------------------------------------------- chunked
        case S.CHUNK_SIZE_START:
          this.setContentLength(0);
          s = S.CHUNK_SIZE_DIGIT;
          continue;

        case S.CHUNK_SIZE_DIGIT:
        case S.CHUNK_SIZE: {
          if (p === end) break;
          const v = hexVal(data[p]);
          if (v >= 0) {
            p++;
            if (this.mulAddContentLength(16, v)) return this.fail(Err.INVALID_CHUNK_SIZE, 'Chunk size overflow', p);
            s = S.CHUNK_SIZE;
            continue;
          }
          if (s === S.CHUNK_SIZE_DIGIT) return this.fail(Err.INVALID_CHUNK_SIZE, 'Invalid character in chunk size', p);
          s = S.CHUNK_SIZE_OTHERWISE;
          continue;
        }

        case S.CHUNK_SIZE_OTHERWISE:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 9) {
            p++;
            if (this.lenient(LENIENT_SPACES_AFTER_CHUNK_SIZE)) continue;
            return this.fail(Err.INVALID_CHUNK_SIZE, 'Invalid character in chunk size', p);
          }
          if (c === 13) {
            p++;
            s = S.CHUNK_SIZE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            p++;
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.CHUNK_SIZE_ALMOST_DONE;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after chunk size', p);
          }
          if (c === 59) {
            p++;
            s = S.CHUNK_EXTENSIONS;
            continue;
          }
          return this.fail(Err.INVALID_CHUNK_SIZE, 'Invalid character in chunk size', p);

        case S.CHUNK_EXTENSIONS:
          if (p === end) break;
          c = data[p];
          if (c === 32 || c === 13) return this.fail(Err.STRICT, 'Invalid character in chunk extensions', p + 1);
          this.spanStart(Span.CHUNK_EXT_NAME, p);
          s = S.CHUNK_EXTENSION_NAME;
          continue;

        case S.CHUNK_EXTENSION_NAME:
          if (p === end) break;
          c = data[p];
          if (TOKEN[c]) {
            p++;
            continue;
          }
          if (c === 61) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, S.CHUNK_EXTENSION_VALUE_START);
            p++;
            s = S.CHUNK_EXTENSION_VALUE_START;
            continue;
          }
          if (c === 59 || c === 13) {
            const next = c === 59 ? S.CHUNK_EXTENSIONS : S.CHUNK_SIZE_ALMOST_DONE;
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, next);
            p++;
            s = next;
            continue;
          }
          if (c === 10) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, S.ERROR);
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.CHUNK_SIZE_ALMOST_DONE;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after chunk extension name', p);
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
          return this.fail(Err.STRICT, 'Invalid character in chunk extensions name', p + 1);

        case S.CHUNK_EXTENSION_VALUE_START:
          if (p === end) break;
          this.spanStart(Span.CHUNK_EXT_VALUE, p);
          s = S.CHUNK_EXTENSION_VALUE;
          continue;

        case S.CHUNK_EXTENSION_VALUE:
          if (p === end) break;
          c = data[p];
          if (c === 34) {
            p++;
            s = S.CHUNK_EXTENSION_QUOTED_VALUE;
            continue;
          }
          if (TOKEN[c]) {
            p++;
            continue;
          }
          if (c === 59 || c === 13) {
            const next = c === 59 ? S.CHUNK_EXTENSIONS : S.CHUNK_SIZE_ALMOST_DONE;
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p + 1, next);
            p++;
            s = next;
            continue;
          }
          if (c === 10) {
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, S.ERROR);
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.CHUNK_SIZE_ALMOST_DONE;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after chunk extension value', p);
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
          return this.fail(Err.STRICT, 'Invalid character in chunk extensions value', p + 1);

        case S.CHUNK_EXTENSION_QUOTED_VALUE:
          if (p === end) break;
          c = data[p];
          if (QUOTED_STRING[c]) {
            p++;
            continue;
          }
          if (c === 34) {
            p++;
            r = this.spanEnd(data, p);
            if (r !== 0) return this.cbFail(r, p, S.CHUNK_EXTENSION_QUOTED_VALUE_DONE);
            s = S.CHUNK_EXTENSION_QUOTED_VALUE_DONE;
            continue;
          }
          if (c === 92) {
            p++;
            s = S.CHUNK_EXTENSION_QUOTED_VALUE_QUOTED_PAIR;
            continue;
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
          return this.fail(Err.STRICT, 'Invalid character in chunk extensions quoted value', p + 1);

        case S.CHUNK_EXTENSION_QUOTED_VALUE_QUOTED_PAIR:
          if (p === end) break;
          if (HTAB_SP_VCHAR_OBS_TEXT[data[p]]) {
            p++;
            s = S.CHUNK_EXTENSION_QUOTED_VALUE;
            continue;
          }
          r = this.spanEnd(data, p);
          if (r !== 0) return this.cbFail(r, p + 1, S.ERROR);
          return this.fail(Err.STRICT, 'Invalid quoted-pair in chunk extensions quoted value', p + 1);

        case S.CHUNK_EXTENSION_QUOTED_VALUE_DONE:
          if (p === end) break;
          c = data[p];
          if (c === 59) {
            p++;
            s = S.CHUNK_EXTENSIONS;
            continue;
          }
          if (c === 13) {
            p++;
            s = S.CHUNK_SIZE_ALMOST_DONE;
            continue;
          }
          if (c === 10) {
            if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
              s = S.CHUNK_SIZE_ALMOST_DONE;
              continue;
            }
            return this.fail(Err.CR_EXPECTED, 'Missing expected CR after chunk extension value', p);
          }
          return this.fail(Err.STRICT, 'Invalid character in chunk extensions quote value', p);

        case S.CHUNK_SIZE_ALMOST_DONE:
          if (p === end) break;
          if (data[p] === 10) {
            p++;
          } else if (!this.lenient(LENIENT_OPTIONAL_LF_AFTER_CR)) {
            return this.fail(Err.STRICT, 'Expected LF after chunk size', p);
          }
          s = S.CHUNK_SIZE_ALMOST_DONE_LF;
          continue;

        case S.CHUNK_SIZE_ALMOST_DONE_LF:
          r = this.settings.onChunkHeader();
          if (r !== 0) {
            if (r === Err.PAUSED) return this.pauseAt('on_chunk_header pause', p, S.TO_CHUNK);
            return this.fail(Err.CB_CHUNK_HEADER, '`on_chunk_header` callback error', p);
          }
          s = S.TO_CHUNK;
          continue;

        case S.TO_CHUNK:
          if (this.content_length === 0 && this.contentLengthBig === null) {
            this.flags |= F_TRAILING;
            s = S.HEADER_FIELD_START;
          } else {
            s = S.CHUNK_DATA;
          }
          continue;

        case S.CHUNK_DATA:
          if (p === end) break;
          this.spanStart(Span.BODY, p);
          s = S.CHUNK_DATA_CONSUME;
          continue;

        case S.CHUNK_DATA_ALMOST_DONE:
          if (p === end) break;
          c = data[p];
          if (this.trie === null) {
            if (c === 10) {
              p++;
              if (this.lenient(LENIENT_OPTIONAL_CR_BEFORE_LF)) {
                s = S.CHUNK_COMPLETE;
                continue;
              }
              return this.fail(Err.CR_EXPECTED, 'Missing expected CR after chunk data', p);
            }
          }
          r = this.stepTrie(T_CRLF, c);
          if (r === TR_MORE) {
            p++;
            continue;
          }
          if (r === TR_DONE) {
            p++;
            s = S.CHUNK_COMPLETE;
            continue;
          }
          if (this.lenient(LENIENT_OPTIONAL_CRLF_AFTER_CHUNK)) {
            s = S.CHUNK_COMPLETE;
            continue;
          }
          return this.fail(Err.STRICT, 'Expected LF after chunk data', p);

        case S.CHUNK_COMPLETE:
          r = this.settings.onChunkComplete();
          if (r !== 0) {
            if (r === Err.PAUSED) return this.pauseAt('on_chunk_complete pause', p, S.CHUNK_SIZE_START);
            return this.fail(Err.CB_CHUNK_COMPLETE, '`on_chunk_complete` callback error', p);
          }
          s = S.CHUNK_SIZE_START;
          continue;

        default:
          return this.fail(Err.INTERNAL, 'Invalid state', p);
      }
      // ran out of input in a node that needs a byte
      this.current = s;
      return 0;
    }
  }

  private pauseAt(reason: string, p: number, next: S, code = Err.PAUSED): number {
    this.error = code;
    this.reason = reason;
    this.error_pos = p;
    this.current = next;
    return code;
  }

  private versionOk(): boolean {
    if (this.lenient(LENIENT_VERSION)) return true;
    const ma = this.http_major;
    const mi = this.http_minor;
    if (ma === 0) return mi === 9;
    if (ma === 1) return mi === 0 || mi === 1;
    if (ma === 2) return mi === 0;
    return false;
  }

  private setHeaderFlags() {
    switch (this.header_state) {
      case HS_CONNECTION_KEEP_ALIVE:
        this.flags |= F_CONNECTION_KEEP_ALIVE;
        this.header_state = HS_CONNECTION;
        break;
      case HS_CONNECTION_CLOSE:
        this.flags |= F_CONNECTION_CLOSE;
        this.header_state = HS_CONNECTION;
        break;
      case HS_CONNECTION_UPGRADE:
        this.flags |= F_CONNECTION_UPGRADE;
        this.header_state = HS_CONNECTION;
        break;
      case HS_TRANSFER_ENCODING_CHUNKED:
        this.flags |= F_CHUNKED;
        break;
    }
  }

  /**
   * The empty line after the headers (or trailers). Returns the negated next state to continue
   * with, or an error/pause code.
   */
  private checkTrailing(p: number): number {
    if (this.flags & F_TRAILING) {
      const r = this.settings.onChunkComplete();
      if (r !== 0) {
        if (r === Err.PAUSED) return this.pauseAt('on_chunk_complete pause', p, S.MESSAGE_DONE);
        return this.fail(Err.CB_CHUNK_COMPLETE, '`on_chunk_complete` callback error', p);
      }
      return -S.MESSAGE_DONE;
    }
    this.beforeHeadersComplete();
    const r = this.settings.onHeadersComplete();
    switch (r) {
      case 0:
        break;
      case 1:
        this.flags |= F_SKIPBODY;
        break;
      case 2:
        this.upgrade = 1;
        this.flags |= F_SKIPBODY;
        break;
      case Err.PAUSED:
        return this.pauseAt('Paused by on_headers_complete', p, S.HEADERS_DONE);
      default:
        return this.fail(Err.CB_HEADERS_COMPLETE, 'User callback error', p);
    }
    return -S.HEADERS_DONE;
  }

  /**
   * The url-terminating peeks shared by server/query/fragment nodes (' ', CR, LF): ends the url
   * span. Returns 0 to continue at `this.current`, a positive error, or -1 if `c` is none of them.
   */
  private urlEnd(data: Uint8Array, p: number, c: number): number {
    let next: S;
    if (c === 32) next = S.URL_SKIP_TO_HTTP;
    else if (c === 13) next = S.URL_SKIP_LF_TO_HTTP09;
    else if (c === 10) next = S.URL_SKIP_TO_HTTP09;
    else return -1;
    const r = this.spanEnd(data, p);
    if (r !== 0) return this.cbFail(r, p, next);
    this.current = next;
    return 0;
  }
}
